import java.util.*;

public class Main {
    boolean canConstruct(String ransomNote, String magazine) {
        List<Character> available = new ArrayList<>();
        for (char ch : magazine.toCharArray()) available.add(ch);
        for (char ch : ransomNote.toCharArray()) {
            if (available.contains(ch)) {
                available.remove((Character) ch);                          // search and remove one matching letter
            } else {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.canConstruct("aa", "aab"));
    }
}

