#include <bits/stdc++.h>
using namespace std;

bool canConstruct(string ransomNote, string magazine) {
    vector<char> available(magazine.begin(), magazine.end());
    for (char ch : ransomNote) {
        auto it = find(available.begin(), available.end(), ch);
        if (it != available.end()) {
            available.erase(it);                                          // search and remove one matching letter
        } else {
            return false;
        }
    }
    return true;
}

int main() {
    cout << (canConstruct("aa", "aab") ? "true" : "false") << endl;
    return 0;
}

