def can_construct(ransom_note, magazine):
    counts = {}
    for ch in magazine:
        counts[ch] = counts.get(ch, 0) + 1                        # tally every letter available in magazine
    for ch in ransom_note:
        if counts.get(ch, 0) == 0:
            return False
        counts[ch] -= 1                                              # use up one instance of this letter
    return True


if __name__ == "__main__":
    print(can_construct("aa", "aab"))

