import java.util.*;

public class Main {
    boolean canConstruct(String ransomNote, String magazine) {
        int[] counts = new int[26];
        for (char ch : magazine.toCharArray()) counts[ch - 'a']++;         // tally every letter available in magazine
        for (char ch : ransomNote.toCharArray()) {
            if (counts[ch - 'a'] == 0) return false;
            counts[ch - 'a']--;                                              // use up one instance of this letter
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.canConstruct("aa", "aab"));
    }
}

